function SixSpurLogo({ size, color }: { size: number; color: string }) {
  return (
    <svg viewBox="0 0 928 1130" width={size} height={size * 1.22} style={{ display: 'block', margin: '0 auto' }}>
      <path fill={color} fillRule="evenodd" d={LOGO_PATH} />
    </svg>
  );
}

export default function AdminHomePage() {
  const [active, setActive] = useState(0);

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      {/* Sidebar */}
      <div style={{ display: 'flex', flexDirection: 'column', width: '200px', borderRight: '1px solid #E8E2DC', flexShrink: 0 }}>
        <div style={{ padding: '20px 16px', textAlign: 'center', borderBottom: '1px solid #E8E2DC', background: '#FFFFFF' }}>
          <div style={{ marginBottom: '8px' }}>
            <SixSpurLogo size={36} color="#111111" />
          </div>
          <div style={{ fontSize: '13px', fontWeight: 500, color: '#111111', lineHeight: 1.3 }}>
            Six Spur Ranch<br />Admin Panel
          </div>
        </div>

        {CATEGORIES.map((name, i) => {
          const isActive = i === active;
          return (
            <div
              key={name}
              onClick={() => setActive(i)}
              style={{
                padding: '14px 16px',
                fontSize: '14px',
                fontWeight: 500,
                textAlign: 'center',
                color: isActive ? '#FFA860' : '#111111',
                background: isActive ? '#111111' : '#FFFFFF',
                borderBottom: '1px solid #E8E2DC',
                cursor: 'pointer',
                transition: 'background 0.12s ease, color 0.12s ease',
              }}
              onMouseEnter={(e) => {
                if (!isActive) {
                  (e.currentTarget as HTMLDivElement).style.background = '#FEF3EB';
                  (e.currentTarget as HTMLDivElement).style.color = '#E77A2D';
                }
              }}
              onMouseLeave={(e) => {
                if (!isActive) {
                  (e.currentTarget as HTMLDivElement).style.background = '#FFFFFF';
                  (e.currentTarget as HTMLDivElement).style.color = '#111111';
                }
              }}
            >
              {name}
            </div>
          );
        })}
      </div>

      {/* Content area */}
      <div style={{ flex: 1, background: '#F7F4F0', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        {active === 0 && (
          <div style={{ textAlign: 'center' }}>
            <div style={{ marginBottom: '12px' }}>
              <SixSpurLogo size={64} color="#111111" />
            </div>
            <div style={{ fontSize: '18px', fontWeight: 500, color: '#111111' }}>
              Six Spur Ranch Admin Panel
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
